 protected function setUp():void{parent::setUp();$this->db=db_connect();$f=Config\Database::forge('tests');foreach($this->tables() as$t)$f->dropTable($t,true);$this->t($f,'academic_years',['code'=>['type'=>'VARCHAR','constraint'=>20],'is_active'=>['type'=>'INTEGER']]);$this->t($f,'academic_periods',['academic_year_id'=>['type'=>'INTEGER'],'semester_code'=>['type'=>'VARCHAR','constraint'=>20],'is_active'=>['type'=>'INTEGER']]);$this->t($f,'study_programs',['code'=>['type'=>'VARCHAR','constraint'=>20],'name'=>['type'=>'VARCHAR','constraint'=>100],'is_active'=>['type'=>'INTEGER']]);$this->t($f,'activity_types',['code'=>['type'=>'VARCHAR','constraint'=>20],'name'=>['type'=>'VARCHAR','constraint'=>100],'is_active'=>['type'=>'INTEGER']]);$this->t($f,'students',['nim'=>['type'=>'VARCHAR','constraint'=>30],'full_name'=>['type'=>'VARCHAR','constraint'=>200]]);$this->t($f,'lecturers',['nidn'=>['type'=>'VARCHAR','constraint'=>30,'null'=>true],'nip'=>['type'=>'VARCHAR','constraint'=>50,'null'=>true],'full_name'=>['type'=>'VARCHAR','constraint'=>200],'bank_name'=>['type'=>'VARCHAR','constraint'=>100,'null'=>true],'bank_account_number'=>['type'=>'VARCHAR','constraint'=>100,'null'=>true],'bank_account_name'=>['type'=>'VARCHAR','constraint'=>200,'null'=>true],'is_active'=>['type'=>'INTEGER']]);$this->t($f,'academic_activities',['activity_no'=>['type'=>'VARCHAR','constraint'=>50],'student_id'=>['type'=>'INTEGER'],'academic_period_id'=>['type'=>'INTEGER'],'study_program_id'=>['type'=>'INTEGER'],'activity_type_id'=>['type'=>'INTEGER'],'title'=>['type'=>'VARCHAR','constraint'=>500,'null'=>true]]);$this->t($f,'activity_assignments',['activity_id'=>['type'=>'INTEGER'],'lecturer_id'=>['type'=>'INTEGER'],'role_type'=>['type'=>'VARCHAR','constraint'=>20],'position_no'=>['type'=>'INTEGER'],'status'=>['type'=>'VARCHAR','constraint'=>20]]);$this->t($f,'student_bills',['bill_no'=>['type'=>'VARCHAR','constraint'=>50],'activity_id'=>['type'=>'INTEGER'],'status'=>['type'=>'VARCHAR','constraint'=>2