 $this->t($f,'honor_rate_settings',['academic_period_id'=>['type'=>'INTEGER'],'study_program_id'=>['type'=>'INTEGER','null'=>true],'activity_type_id'=>['type'=>'INTEGER'],'role_type'=>['type'=>'VARCHAR','constraint'=>20],'position_no'=>['type'=>'INTEGER'],'gross_amount'=>['type'=>'DECIMAL','constraint'=>'15,2'],'tax_rate_percent'=>['type'=>'DECIMAL','constraint'=>'7,4'],'version_no'=>['type'=>'INTEGER'],'effective_start_date'=>['type'=>'DATE','null'=>true],'effective_end_date'=>['type'=>'DATE','null'=>true],'is_active'=>['type'=>'INTEGER'],'notes'=>['type'=>'TEXT','null'=>true],'created_at'=>['type'=>'DATETIME','null'=>true],'updated_at'=>['type'=>'DATETIME','null'=>true]]);$this->t($f,'honor_entitlements',['assignment_id'=>['type'=>'INTEGER'],'honor_rate_setting_id'=>['type'=>'INTEGER'],'gross_amount_snapshot'=>['type'=>'DECIMAL','constraint'=>'15,2'],'tax_rate_snapshot'=>['type'=>'DECIMAL','constraint'=>'7,4'],'tax_amount'=>['type'=>'DECIMAL','constraint'=>'15,2'],'net_amount'=>['type'=>'DECIMAL','constraint'=>'15,2'],'status'=>['type'=>'VARCHAR','constraint'=>25],'notes'=>['type'=>'TEXT','null'=>true],'created_at'=>['type'=>'DATETIME','null'=>true],'updated_at'=>['type'=>'DATETIME','null'=>true]]);$this->t($f,'honor_payment_batches',['batch_no'=>['type'=>'VARCHAR','constraint'=>50],'academic_period_id'=>['type'=>'INTEGER'],'payment_date'=>['type'=>'DATE','null'=>true],'status'=>['type'=>'VARCHAR','constraint'=>20],'reference_no'=>['type'=>'VARCHAR','constraint'=>100,'null'=>true],'proof_file_path'=>['type'=>'TEXT','null'=>true],'notes'=>['type'=>'TEXT','null'=>true],'created_at'=>['type'=>'DATETIME','null'=>true],'updated_at'=>['type'=>'DATETIME','null'=>true]]);$this->t($f,'honor_payments',['honor_payment_batch_id'=>['type'=>'INTEGER'],'lecturer_id'=>['type'=>'INTEGER'],'payment_method_id'=>['type'=>'INTEGER','null'=>true],'bank_name_snapshot'=>['type'=>'VARCHAR','constraint'=>100,'null'=>true],'bank_account_number_snapshot'=>['type'=>'VARCHAR','constraint'=>100,'null'=>true],'bank_account_name_snapshot'=>['type'=>'VARCHAR','constraint'=>200,'null'=>true],'gross_total'=>['type'=>'DECIMAL','constraint'=>'15,2'],'tax_total'=>['type'=>'DECIMAL','constraint'=>'15,2'],'net_total'=>['type'=>'DECIMAL','constraint'=>'15,2'],'status'=>['type'=>'VARCHAR','constraint'=>20],'paid_at'=>['type'=>'DATETIME','null'=>true],'notes'=>['type'=>'TEXT','null'=>true],'created_at'=>['type'=>'DATETIME','null'=>true],'updated_at'=>['type'=>'DATETIME','null'=>true]]);$this->t($f,'honor_payment_items',['honor_payment_id'=>['type'=>'INTEGER'],'honor_entitlement_id'=>['type'=>'INTEGER'],'gross_amount'=>['type'=>'DECIMAL','constraint'=>'15,2'],'tax_amount'=>['type'=>'DECIMAL','constraint'=>'15,2'],'net_amount'=>['type'=>'DECIMAL','constraint'=>'15,2'],'created_at'=>['type'=>'DATETIME','null'=>true]]);$this->t($f,'payment_methods',['code'=>['type'=>'VARCHAR','constraint'=>20],'name'=>['type'=>'VARCHAR','constraint'=>100],'is_active'=>['type'=>'INTEGER']]);$this->audit($f);$this->seed();}
 protected function tearDown():void{$f=Config\Database::forge('tests');foreach($this->tables()as$t)$f->dropTable($t,true);parent::tearDown();}
 public function testHonorPagesUseTheirAngularControllers():void{$this->assertStringContainsString('tarifHonorController',$this->admin()->get('/honor/tarif')->getBody());$hak=$this->admin()->get('/honor/hak')->getBody();$this->assertStringContainsString('hakHonorController',$hak);$this->assertStringNotContainsString('Ajukan hak honor',$hak);$this->assertStringContainsString('dibuat otomatis saat tagihan mahasiswa diterbitkan',$hak);$this->assertStringContainsString('batchHonorController',$this->admin()->get('/honor/pembayaran')->getBody());}
 public function testManualEntitlementEndpointIsUnavailable():void{$this->expectException(\CodeIgniter\Exceptions\PageNotFoundException::class);$this->mut()->post('/honor/hak/post',['assignment_id'=>$this->assignment]);}
 public function testGroupedExportKeepsOldDetailAndNumbersRepeatedRoles():void{$batch=['batch_no'=>'HNR-TEST','academic_year_code'=>'2026/2027','semester_code'=>'GANJIL','status'=>'DRAFT','payment_date'=>null,'reference_no'=>null,'lecturer_count'=>1,'net_total'=>1900000];$base=['lecturer_id'=>1,'full_name'=>'Dosen Uji','nidn'=>'001','nip'=>'','bank_name_snapshot'=>'Bank Uji','bank_account_number_snapshot'=>'123','bank_account_name_snapshot'=>'Dosen Uji','payment_status'=>'DRAFT','activity_id'=>1,'activity_no'=>'KGT-1','activity_name'=>'Seminar','student_name'=>'Mahasiswa Uji','role_type'=>'PEMBIMBING','role_count'=>2,'gross_amount'=>1000000,'tax_amount'=>50000,'net_amount'=>950000];$path=(new App\Libraries\HonorBatchExporter())->export($batch,[[...$base,'position_no'=>1],[...$base,'position_no'=>2]]);$zip=new ZipArchive();$this->assertTrue($zip->open($path)===true);$workbook=$zip->getFromName('xl/workbook.xml');$all='';for($i=0;$i<$zip->numFiles;$i++){if(str_starts_with($zip->getNameIndex($i),'xl/worksheets/'))$all.=$zip->getFromIndex($i);}$zip->close();@unlink($path);$this->assertStringContainsString('Detail Honor',$workbook);$this->assertStringContainsString('Rekap per Dosen',$workbook);$this->assertStringContainsString('Pembimbing 1',$all);$this->assertStringContainsString('Pembimbing 2',$all);$this->assertStringContainsString('Mahasiswa Uji',$all);}
 public function testEntitlementCannotBeApprovedBeforeStudentBillIsPaid():void{$rate=$this->mut()->post('/honor/tarif/post',['study_program_id'=>$this->program,'activity_type_id'=>$this->type,'role_type'=>'PEMBIMBING','position_no'=>1,'gross_amount'=>1000000,'tax_rate_percent'=>5]);$rateId=(int)json_decode((string)$rate->getJSON(),true)['data']['id'];$now=date('Y-m-d H:i:s');$this->db->table('honor_entitlements')->insert(['assignment_id'=>$this->assignment,'honor_rate_setting_id'=>$rateId,'gross_amount_snapshot'=>1000000,'tax_rate_snapshot'=>5,'tax_amount'=>50000,'net_amount'=>950000,'status'=>'DIAJUKAN','created_at'=>$now,'updated_at'=>$now]);$eid=(int)$this->db->insertID();$this->db->table('student_bills')->where('activity_id',$this->activity)->update(['status'=>'BELUM_DIBAYAR']);$response=$this->mut()->post('/honor/hak/setujui/'.$eid,[]);$response->assertStatus(422);$this->assertStringContainsString('berstatus LUNAS',json_decode((string)$response->getJSON(),true)['message']);$this->assertSame('DIAJUKAN',$this->db->table('honor_entitlements')->where('id',$eid)->get()->getRow('status'));}
 public function testCompleteHonorWorkflow():void{$rate=$this->mut()->post('/honor/tarif/post',['study_program_id'=>$this->program,'activity_type_id'=>$this->type,'role_type'=>'PEMBIMBING','position_no'=>1,'gross_amount'=>1000000,'tax_rate_percent'=>5]);$rate->assertStatus(201);$rateId=(int)json_decode((string)$rate->getJSON(),true)['data']['id'];$now=date('Y-m-d H:i:s');$this->db->table('honor_entitlements')->insert(['assignment_id'=>$this->assignment,'honor_rate_setting_id'=>$rateId,'gross_amount_snapshot'=>1000000,'tax_rate_snapshot'=>5,'tax_amount'=>50000,'net_amount'=>950000,'status'=>'DIAJUKAN','notes'=>'Dibuat otomatis dari tagihan pengujian','created_at'=>$now,'updated_at'=>$now]);$eid=(int)$this->db->insertID();$row=$this->db->table('honor_entitlements')->where('id',$eid)->get()->getRowArray();$this->assertSame(50000,(int)$row['tax_amount']);$this->assertSame(950000,(int)$row['net_amount']);$this->mut()->post('/honor/hak/setujui/'.$eid,[])->assertStatus(200);$batch=$this->mut()->post('/honor/pembayaran/post',['entitlement_ids'=>[$eid]]);$batch->assertStatus(201);$bid=(int)json_decode((string)$batch->getJSON(),true)['data']['id'];$this->assertSame('DIPROSES',$this->db->table('honor_entitlements')->where('id',$eid)->get()->getRow('status'));$detail=$this->admin()->get('/honor/pembayaran/detail/'.$bid);$detail->assertStatus(200);$this->assertCount(1,json_decode((string)$detail->getJSON(),true)['data']['items']);$this->admin()->get('/honor/pembayaran/export/'.$bid)->assertStatus(200);$this->mut()->post('/honor/pembayaran/bayar/'.$bid,['payment_method_id'=>$this->method,'payment_date'=>'2026-10-01','reference_no'=>'HNR-REF'])->assertStatus(200);$this->assertSame('DIBAYAR',$this->db->table('honor_entitlements')->where('id',$eid)->get()->getRow('status'));$this->assertSame('DIBAYAR',$this->db->table('honor_payment_batches')->where('id',$bid)->get()->getRow('status'));}
 private function seed():void{$this->db->table('academic_years')->insert(['code'=>'2026/2027','is_active'=>1]);$y=(int)$this->db->insertID();$this->db->table('academic_periods')->insert(['academic_year_id'=>$y,'semester_code'=>'GANJIL','is_active'=>1]);$this->period=(int)$this->db->insertID();$this->db->table('study_programs')->insert(['code'=>'TI','name'=>'Teknik Informatika','is_active'=>1]);$this->program=(int)$this->db->insertID();$this->db->table('activity_types')->insert(['code'=>'SEM','name'=>'Seminar','is_active'=>1]);$this->type=(int)$this->db->insertID();$this->db->table('students')->insert(['nim'=>'2026001','full_name'=>'Mahasiswa Uji']);$student=(int)$this->db->insertID();$this->db->table('lecturers')->insert(['nidn'=>'001','full_name'=>'Dosen Uji','bank_name'=>'Bank Uji','bank_account_number'=>'123','bank_account_name'=>'Dosen Uji','is_active'=>1]);$l=(int)$this->db->insertID();$this->db->table('academic_activities')->insert(['activity_no'=>'KGT-1','student_id'=>$student,'academic_period_id'=>$this->period,'study_program_id'=>$this->program,'activity_type_id'=>$this->type,'title'=>'Seminar']);$this->activity=(int)$this->db->insertID();$this->db->table('activity_assignments')->insert(['activity_id'=>$this->activity,'lecturer_id'=>$l,'role_type'=>'PEMBIMBING','position_no'=>1,'status'=>'AKTIF']);$this->assignment=(int)$this->db->insertID();$this->db->table('student_bills')->insert(['bill_no'=>'INV-001','activity_id'=>$this->activity,'status'=>'LUNAS']);$this->db->table('payment_methods')->insert(['code'=>'TRF','name'=>'Transfer','is_active'=>1]);$this->method=(int)$this->db->insertID();}
 private function tables():array{return['audit_logs','honor_payment_items','honor_payments','honor_payment_batches','honor_entitlements','honor_rate_settings','student_bills','activity_assignments','academic_activities','payment_methods','lecturers','students','activity_types','study_programs','academic_periods','academic_years'];}private function t($f,$n,$x):void{$f->addField(array_merge(['id'=>['type'=>'INTEGER','auto_increment'=>true]],$x));$f->addKey('id',true);$f->createTable($n);}private function audit($f):void{$this->t($f,'audit_logs',['user_id'=>['type'=>'INTEGER','null'=>true],'action'=>['type'=>'VARCHAR','constraint'=>100],'entity_type'=>['type'=>'VARCHAR','constraint'=>100],'entity_id'=>['type'=>'INTEGER','null'=>true],'old_values'=>['type'=>'TEXT','null'=>true],'new_values'=>['type'=>'TEXT','null'=>true],'ip_address'=>['type'=>'VARCHAR','constraint'=>45,'null'=>true],'created_at'=>['type'=>'DATETIME','null'=>true]]);}private function admin():self{return$this->withSession(['auth'=>['id'=>1,'role'=>'ADMIN','username'=>'admin','full_name'=>'Admin']]);}private function mut():self{helper('form');return$this->admin()->withHeaders([config('Security')->headerName=>csrf_hash()])->withBodyFormat('json');}}
